const input=$json.body??$json;
const blockers=Array.isArray(input.blockers)?input.blockers:[];
const dnc=Boolean(input.dnc||input.do_not_contact);
const leadId=input.lead_id, dealId=input.deal_id, propertyId=input.property_id;
const contractPrice=Number(input.contract_price??input.offer_price??input.accepted_price);
const mao=Number(input.dynamic_mao??input.adjusted_mao??input.mao);
const agreementType=String(input.agreement_type??input.contract_type??"").trim();
const sellerName=String(input.seller_name??input.seller?.name??"").trim();
const sellerEmail=String(input.seller_email??input.seller?.email??"").trim();
const sellerPhone=String(input.seller_phone??input.seller?.phone??"").trim();
const signatureRequired=input.signature_required!==false;
const signatureProvider=String(input.signature_provider??"").trim();
const identityReady=Boolean(leadId&&dealId&&propertyId&&sellerName&&(sellerEmail||sellerPhone));
const priceReady=Number.isFinite(contractPrice)&&contractPrice>0&&Number.isFinite(mao)&&mao>0&&contractPrice<=mao;
const agreementReady=Boolean(agreementType);
let status="blocked",decision="blocked",nextWorkflow="WF-126",human=true,reason="";
if(dnc){reason="seller is marked DNC; contract launch blocked";}
else if(blockers.length){reason="active blockers prevent contract launch";}
else if(!identityReady){reason="lead/deal/property identity or seller contact evidence is incomplete";}
else if(!priceReady){reason="contract price is invalid or exceeds protected dynamic MAO";}
else if(!agreementReady){reason="agreement type is missing";}
else if(!signatureRequired){status="contract_ready";decision="contract_ready";nextWorkflow="WF-302";human=true;reason="contract package is validated and ready for execution path";}
else if(!signatureProvider){status="signature_provider_required";decision="signature_provider_required";nextWorkflow="WF-126";reason="signature is required but no signature provider is configured";}
else{status="signature_launch_ready";decision="signature_launch_ready";nextWorkflow="WF-302";human=true;reason="contract package validated; signature launch requires human authorization";}
const idempotencyKey=input.idempotency_key||`wf-301:${dealId||"unknown"}:${input.contract_version||input.version||1}`;
return [{json:{...input,workflow:"WF-301",workflow_name:"Contract-Ready Decision → Contract Package Validation & Signature Launch Controller",status,contract_package:{decision,contract_price:Number.isFinite(contractPrice)?contractPrice:null,dynamic_mao:Number.isFinite(mao)?mao:null,agreement_type:agreementType||null,seller:{name:sellerName||null,email:sellerEmail||null,phone:sellerPhone||null},signature_required:signatureRequired,signature_provider:signatureProvider||null,identity_ready:identityReady,price_protected:priceReady},next_workflow:nextWorkflow,human_review_required:human,audit:{event_type:"contract_package_validation",idempotency_key:idempotencyKey,reason}}}];
